import{_ as n,H as a,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"06｜去芜存菁 ：高噪声任务处理——测试运行器与日志分析器","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么需要“噪声隔离”？——从 token 消耗说起","slug":"为什么需要-噪声隔离-——从-token-消耗说起","link":"#为什么需要-噪声隔离-——从-token-消耗说起","children":[]},{"level":2,"title":"信噪比决策框架","slug":"信噪比决策框架","link":"#信噪比决策框架","children":[]},{"level":2,"title":"项目一：测试运行器","slug":"项目一-测试运行器","link":"#项目一-测试运行器","children":[{"level":3,"title":"实战项目结构配置","slug":"实战项目结构配置","link":"#实战项目结构配置","children":[]},{"level":3,"title":"创建测试运行子代理","slug":"创建测试运行子代理","link":"#创建测试运行子代理","children":[]},{"level":3,"title":"使用测试运行器","slug":"使用测试运行器","link":"#使用测试运行器","children":[]}]},{"level":2,"title":"项目二：日志分析器","slug":"项目二-日志分析器","link":"#项目二-日志分析器","children":[{"level":3,"title":"实战项目结构配置","slug":"实战项目结构配置-1","link":"#实战项目结构配置-1","children":[]},{"level":3,"title":"创建日志分析子代理","slug":"创建日志分析子代理","link":"#创建日志分析子代理","children":[]},{"level":3,"title":"使用日志分析器","slug":"使用日志分析器","link":"#使用日志分析器","children":[]}]},{"level":2,"title":"输出格式设计方法论","slug":"输出格式设计方法论","link":"#输出格式设计方法论","children":[]},{"level":2,"title":"本讲小结","slug":"本讲小结","link":"#本讲小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"下一讲预告","slug":"下一讲预告","link":"#下一讲预告","children":[]}],"relativePath":"ClaudeCode工程化实战/06｜去芜存菁：高噪声任务处理——测试运行器与日志分析器.md","filePath":"ClaudeCode工程化实战/06｜去芜存菁：高噪声任务处理——测试运行器与日志分析器.md","lastUpdated":1779815462000}'),l={name:"ClaudeCode工程化实战/06｜去芜存菁：高噪声任务处理——测试运行器与日志分析器.md"};function i(t,s,c,o,r,d){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="_06-去芜存菁-高噪声任务处理——测试运行器与日志分析器" tabindex="-1">06｜去芜存菁 ：高噪声任务处理——测试运行器与日志分析器 <a class="header-anchor" href="#_06-去芜存菁-高噪声任务处理——测试运行器与日志分析器" aria-label="Permalink to &quot;06｜去芜存菁 ：高噪声任务处理——测试运行器与日志分析器&quot;">​</a></h1><p>你好，我是黄佳。欢迎来到 Claude Code 工程化实战的第 6 讲。</p><p>上一讲我们学习了如何创建只读型子代理来实现权限边界。今天我们要处理另一类重要场景： <strong>高噪声输出任务</strong>。</p><p>什么是高噪声输出？</p><p>在下面的场景中：你让 Claude Code 帮你跑一下测试，它执行 <code>npm test</code>，然后……</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PASS  src/utils/format.test.js</span></span>
<span class="line"><span>    console.log src/utils/format.js:12</span></span>
<span class="line"><span>      Formatting date: 2024-01-15T09:30:00.000Z</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS  src/utils/validate.test.js</span></span>
<span class="line"><span>PASS  src/components/Button.test.js</span></span>
<span class="line"><span>    console.warn src/components/Button.js:45</span></span>
<span class="line"><span>      Deprecation warning: Use &#39;variant&#39; instead of &#39;type&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS  src/components/Input.test.js</span></span>
<span class="line"><span>FAIL  src/components/Form.test.js</span></span>
<span class="line"><span>    Form › submits data correctly</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    expect(received).toEqual(expected)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Expected: {&quot;name&quot;: &quot;John&quot;, &quot;email&quot;: &quot;john&amp;#64;example.com&quot;}</span></span>
<span class="line"><span>    Received: {&quot;name&quot;: &quot;John&quot;, &quot;email&quot;: &quot;&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      at Object.&amp;lt;anonymous&amp;gt; (src/components/Form.test.js:45:23)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS  src/services/api.test.js</span></span>
<span class="line"><span>... 还有 300 行 ...</span></span></code></pre></div><p>想想看这 300+ 行输出，你真正关心的是什么？ <strong>就一句话：发现 1 个测试失败，是来自 Form 组件的提交功能。</strong></p><p>子代理的价值就在这里：它去执行这些高噪声任务，然后只把 <strong>结论</strong> 带回主对话。</p><p>今天我们要创建两个子代理。一个是 <strong>测试运行器</strong>，负责执行测试，总结结果。另一个是 <strong>日志分析器</strong>，用来分析日志，提取关键问题。</p><p>要分析的代码示例和子代理都非常简单，易于理解，所以更重要的学习目标还有两个。</p><ol><li><p>理解 <strong>“信噪比”框架</strong>，学会判断哪些任务适合委托给子代理。</p></li><li><p>掌握 <strong>子代理输出格式设计的方法论</strong>，而非只学一个固定模板。</p></li></ol><p>这些框架和方法，会为我们在实操过程中明确：什么时候需要引入子代理，并形成一套原则性的设计思路。</p><h2 id="为什么需要-噪声隔离-——从-token-消耗说起" tabindex="-1">为什么需要“噪声隔离”？——从 token 消耗说起 <a class="header-anchor" href="#为什么需要-噪声隔离-——从-token-消耗说起" aria-label="Permalink to &quot;为什么需要“噪声隔离”？——从 token 消耗说起&quot;">​</a></h2><p>我们已经在课程和评论区中多次区分过 Skill 和 Sub-agent 的本质差异。这里要把那个抽象概念落地为一个可量化的工程问题。</p><p>噪声留在主对话的真实代价是什么？假设你在主对话中直接执行 <code>npm test</code>，测试输出 300 行：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主对话上下文变化：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行前：</span></span>
<span class="line"><span>├── 之前 5 轮对话           ≈ 3,000 tokens</span></span>
<span class="line"><span>├── 当前需求讨论             ≈ 500 tokens</span></span>
<span class="line"><span>└── 总计                    ≈ 3,500 tokens</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行后：</span></span>
<span class="line"><span>├── 之前 5 轮对话           ≈ 3,000 tokens</span></span>
<span class="line"><span>├── 当前需求讨论             ≈ 500 tokens</span></span>
<span class="line"><span>├── npm test 输出（300行）   ≈ 4,500 tokens  ← 噪声</span></span>
<span class="line"><span>├── Claude 的分析            ≈ 800 tokens</span></span>
<span class="line"><span>└── 总计                    ≈ 8,800 tokens</span></span></code></pre></div><p>问题不只是多花了 token，更关键的是 <strong>后续每轮对话都要带着这 4,500 tokens 的噪声</strong>。如果你之后又跑了一次测试、查了一次日志，主对话的上下文会迅速膨胀，Claude 的注意力被稀释，回答质量下降。</p><p>子代理隔离后的效果如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主对话上下文变化：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>├── 之前 5 轮对话           ≈ 3,000 tokens</span></span>
<span class="line"><span>├── 当前需求讨论             ≈ 500 tokens</span></span>
<span class="line"><span>├── 子代理返回的摘要          ≈ 200 tokens  ← 精炼结果</span></span>
<span class="line"><span>└── 总计                    ≈ 3,700 tokens</span></span>
<span class="line"><span></span></span>
<span class="line"><span>子代理上下文（执行完即释放）：</span></span>
<span class="line"><span>├── prompt 指令              ≈ 500 tokens</span></span>
<span class="line"><span>├── npm test 输出（300行）   ≈ 4,500 tokens</span></span>
<span class="line"><span>├── 分析过程                 ≈ 800 tokens</span></span>
<span class="line"><span>└── 总计                    ≈ 5,800 tokens（不影响主对话）</span></span></code></pre></div><p>主对话从 8,800 tokens 降到 3,700 tokens，减少 58%。更重要的是，后续对话不需要反复携带测试输出的噪声。</p><h2 id="信噪比决策框架" tabindex="-1">信噪比决策框架 <a class="header-anchor" href="#信噪比决策框架" aria-label="Permalink to &quot;信噪比决策框架&quot;">​</a></h2><p>不是所有任务都需要子代理来处理。判断标准是 <strong>信噪比</strong>——输出中你真正需要的信息占总输出的比例。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/800451ce2fc698f5050d7aeyy45ae35a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/800451ce2fc698f5050d7aeyy45ae35a.jpg" alt=""></a></p><p>这里有一个经验法则：如果一个命令的输出超过 50 行（行数也还要视具体情况而定），且你只关心其中不到 10 行（也就是不到五分之一）的内容，就应该用子代理。</p><h2 id="项目一-测试运行器" tabindex="-1">项目一：测试运行器 <a class="header-anchor" href="#项目一-测试运行器" aria-label="Permalink to &quot;项目一：测试运行器&quot;">​</a></h2><p>测试运行是最典型的高噪声场景：输入 <code>npm test</code>，输出几十到几百行日志。我们关心的只是通过/失败？失败了哪个？为什么？目标是让子代理去消化这些输出，只返回你需要做决策的信息。</p><h3 id="实战项目结构配置" tabindex="-1">实战项目结构配置 <a class="header-anchor" href="#实战项目结构配置" aria-label="Permalink to &quot;实战项目结构配置&quot;">​</a></h3><p>实战项目位于 <code>03-SubAgents/projects/01-test-runner/</code>，项目结构如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01-test-runner/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── calculator.js       # 被测试的模块</span></span>
<span class="line"><span>│   └── calculator.test.js  # 测试文件（故意包含一个会失败的测试）</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>└── .claude/agents/</span></span>
<span class="line"><span>    └── test-runner.md      # 测试运行子代理配置</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/a0f1995a1c87656e090fb4d58c5d4118.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/a0f1995a1c87656e090fb4d58c5d4118.png" alt="图片"></a></p><p>让我简单说明一下该目录中的各个文件。被测试的代码 <code>calculator.js</code> 是一个简单的计算器模块。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function add(a, b) {</span></span>
<span class="line"><span>  return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function subtract(a, b) {</span></span>
<span class="line"><span>  return a - b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function multiply(a, b) {</span></span>
<span class="line"><span>  return a * b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function divide(a, b) {</span></span>
<span class="line"><span>  if (b === 0) {</span></span>
<span class="line"><span>    throw new Error(&#39;Division by zero&#39;);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  return a / b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 故意的 bug：没有处理负数的情况</span></span>
<span class="line"><span>function factorial(n) {</span></span>
<span class="line"><span>  if (n === 0 || n === 1) return 1;</span></span>
<span class="line"><span>  return n * factorial(n - 1);</span></span>
<span class="line"><span>  // 如果 n &amp;lt; 0，会无限递归导致栈溢出</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>module.exports = { add, subtract, multiply, divide, factorial };</span></span></code></pre></div><p>测试代码 <code>calculator.test.js</code> 中包含了一个会失败的测试：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ... 前面的测试都会通过 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 这个测试会暴露 bug：负数会导致无限递归</span></span>
<span class="line"><span>test(&#39;handles negative numbers gracefully&#39;, () =&amp;gt; {</span></span>
<span class="line"><span>  // 期望抛出错误，但实际会栈溢出</span></span>
<span class="line"><span>  assertThrows(() =&amp;gt; factorial(-1), &#39;negative&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre></div><h3 id="创建测试运行子代理" tabindex="-1">创建测试运行子代理 <a class="header-anchor" href="#创建测试运行子代理" aria-label="Permalink to &quot;创建测试运行子代理&quot;">​</a></h3><p>最关键的步骤是创建测试运行子代理，参考 <code>.claude/agents/test-runner.md</code> 中的配置。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: test-runner</span></span>
<span class="line"><span>description: Run tests and report results concisely. Use this after code changes to verify everything works.</span></span>
<span class="line"><span>tools: Read, Bash, Glob, Grep</span></span>
<span class="line"><span>model: haiku</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are a test execution specialist.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>When invoked:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. First, identify the test command by checking package.json or common patterns:</span></span>
<span class="line"><span>   - Node.js: \`npm test\` or \`node **/*.test.js\`</span></span>
<span class="line"><span>   - Python: \`pytest\` or \`python -m unittest\`</span></span>
<span class="line"><span>   - Go: \`go test ./...\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Run the tests and capture the output</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Analyze the results and provide a **concise summary**:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>------------</span></span>
<span class="line"><span>## Test Results</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Status**: PASS / FAIL</span></span>
<span class="line"><span>**Total**: X tests</span></span>
<span class="line"><span>**Passed**: X</span></span>
<span class="line"><span>**Failed**: X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Failed Tests (if any)</span></span>
<span class="line"><span>- test_name: brief reason</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Recommendations (if failures)</span></span>
<span class="line"><span>- What to check/fix</span></span>
<span class="line"><span>------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Guidelines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Keep the summary SHORT - the user doesn&#39;t want to see raw logs</span></span>
<span class="line"><span>- Focus on actionable information</span></span>
<span class="line"><span>- Group similar failures together</span></span>
<span class="line"><span>- If all tests pass, just say so briefly</span></span></code></pre></div><p>子代理的配置如下表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/74af462d2a2376e1f175b66430716bed.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/74af462d2a2376e1f175b66430716bed.jpg" alt=""></a></p><p>我们重点看一下最后一行， <code>haiku</code> 是一个关键决策：为什么用 haiku 而不是 sonnet？</p><p>先复习一下各种模型所适合的场景。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/6f5cb7c2de99643bd4bdefe7d0c380f9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/6f5cb7c2de99643bd4bdefe7d0c380f9.jpg" alt=""></a></p><p>因为测试运行器的任务相对简单：执行命令是固定化流程，解析输出是模式匹配任务，生成报告只需按模板填充即可。这些任务 <code>haiku</code> 完全胜任，而且更快、更便宜。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/6979d5d7355b6cbafe822fbe6d70f520.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/6979d5d7355b6cbafe822fbe6d70f520.jpg" alt=""></a></p><h3 id="使用测试运行器" tabindex="-1">使用测试运行器 <a class="header-anchor" href="#使用测试运行器" aria-label="Permalink to &quot;使用测试运行器&quot;">​</a></h3><p>下面进入项目目录，在 Claude Code 中显式调用它（就是指出子代理的名称test-runner ）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>让 test-runner 跑一下测试</span></span></code></pre></div><p>示例输出如下（过程中人类需要确定给与某些命令的执行权限）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/7d8dc92f81429c15aea703c38b438733.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/7d8dc92f81429c15aea703c38b438733.png" alt="图片"></a></p><p>Claude Code经常提示人类用户确定Claude在当前场景中的权限设置。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/2a55b9c84ce30997a765b1ff11ed70e2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/2a55b9c84ce30997a765b1ff11ed70e2.png" alt="图片"></a></p><p>也可以通过自然语言触发（这里不显式指出子代理的名称test-runner，留给 Claude 自动选择）。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调用相关的Agent帮我跑一下测试看看有没有问题</span></span>
<span class="line"><span>（或者）检查一下测试是否都通过 （注意：此时并不能确定是否会百分之百触发test-runner）</span></span></code></pre></div><p>在我自己的测试过程中，如果不强调调用Agent，并不能确定是否会百分之百触发 test-runner子代理。然而重要的是，一旦Sub-Agent触发，子代理只返回关键信息（完整的测试输出可能有 100+ 行）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/89430f4ecfb4a72d52bb2398cf2e3df9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/89430f4ecfb4a72d52bb2398cf2e3df9.png" alt="图片"></a></p><p>这样，主对话的上下文没有被几十行甚至成千上百行的测试日志污染，你可以直接基于这个摘要做决策。</p><h2 id="项目二-日志分析器" tabindex="-1">项目二：日志分析器 <a class="header-anchor" href="#项目二-日志分析器" aria-label="Permalink to &quot;项目二：日志分析器&quot;">​</a></h2><p>日志分析是另一个典型的高噪声场景，而且噪声更大：</p><ul><li><p>应用日志通常有几千到几百万行，此时我们关心的是有什么错误？根因是什么？</p></li><li><p>生产事故的特点是在短时间内出现大量错误，需要确定第一个错误是什么？影响范围多大？</p></li><li><p>性能问题会出现大量慢请求日志，要分析哪些请求慢？有什么规律？</p></li></ul><h3 id="实战项目结构配置-1" tabindex="-1">实战项目结构配置 <a class="header-anchor" href="#实战项目结构配置-1" aria-label="Permalink to &quot;实战项目结构配置&quot;">​</a></h3><p>实战项目位于 <code>03-SubAgents/projects/03-log-analyzer/</code>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>03-log-analyzer/</span></span>
<span class="line"><span>├── logs/</span></span>
<span class="line"><span>│   ├── app.log       # 应用日志（混合 INFO/WARN/ERROR）</span></span>
<span class="line"><span>│   ├── error.log     # 错误日志</span></span>
<span class="line"><span>│   └── access.log    # 访问日志</span></span>
<span class="line"><span>└── .claude/agents/</span></span>
<span class="line"><span>    └── log-analyzer.md</span></span></code></pre></div><p><code>error.log</code> 中包含了多种类型的错误：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2024-01-15 09:03:00.123 ERROR [db] Database connection timeout after 5000ms</span></span>
<span class="line"><span>  Connection: mysql://app_user&amp;#64;db-primary:3306/production</span></span>
<span class="line"><span>  Query: SELECT * FROM orders WHERE user_id = 123 AND status = &#39;pending&#39;</span></span>
<span class="line"><span>  Waited: 5000ms</span></span>
<span class="line"><span>  Pool status: 0/10 available</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2024-01-15 09:06:31.012 ERROR [auth] Too many failed attempts, account locked: admin</span></span>
<span class="line"><span>  IP: 203.0.113.50</span></span>
<span class="line"><span>  Attempts: 5</span></span>
<span class="line"><span>  Window: 60s</span></span>
<span class="line"><span>  Action: Account locked for 15 minutes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2024-01-15 09:35:15.890 ERROR [api] Unhandled exception in /api/products</span></span>
<span class="line"><span>  Request ID: req_abc123</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TypeError: Cannot read property &#39;price&#39; of undefined</span></span>
<span class="line"><span>    at ProductService.calculateTotal (/app/services/product.js:45)</span></span>
<span class="line"><span>    at ProductController.getProduct (/app/controllers/product.js:23)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2024-01-15 10:25:00.789 ERROR [db] Database connection timeout after 5000ms</span></span>
<span class="line"><span>  Connection: mysql://app_user&amp;#64;db-primary:3306/production</span></span>
<span class="line"><span>  Pool status: 0/10 available</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2024-01-15 10:25:01.012 ERROR [db] Database connection timeout after 5000ms</span></span>
<span class="line"><span>  Connection: mysql://app_user&amp;#64;db-primary:3306/production</span></span>
<span class="line"><span>  Pool status: 0/10 available</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2024-01-15 10:45:30.678 ERROR [cache] Redis connection lost</span></span>
<span class="line"><span>  Server: redis-primary:6379</span></span>
<span class="line"><span>  Error: ECONNRESET</span></span></code></pre></div><p>人眼看这些日志，很难快速发现规律。但子代理可以帮我们完成以下任务。</p><ul><li><p>统计错误类型和频率</p></li><li><p>发现重复模式（比如数据库超时反复出现）</p></li><li><p>建立时间线（哪个错误先发生？可能是根因）</p></li><li><p>识别关联（数据库超时是否影响了其他服务？）</p></li></ul><h3 id="创建日志分析子代理" tabindex="-1">创建日志分析子代理 <a class="header-anchor" href="#创建日志分析子代理" aria-label="Permalink to &quot;创建日志分析子代理&quot;">​</a></h3><p>在 <code>.claude/agents/log-analyzer.md</code> 中，进行如下配置：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: log-analyzer</span></span>
<span class="line"><span>description: Analyze log files and extract actionable insights. Use when troubleshooting issues or investigating incidents.</span></span>
<span class="line"><span>tools: Read, Grep, Glob, Bash</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are a senior SRE (Site Reliability Engineer) specialized in log analysis and incident investigation.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## When Invoked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **Identify Log Files**: Use Glob to find relevant log files</span></span>
<span class="line"><span>2. **Scan for Issues**: Grep for ERROR, WARN, exceptions</span></span>
<span class="line"><span>3. **Analyze Patterns**: Identify recurring issues and correlations</span></span>
<span class="line"><span>4. **Provide Insights**: Actionable summary with root cause analysis</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Analysis Approach</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 1: Quick Scan</span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span># Count errors by type</span></span>
<span class="line"><span>grep -c &quot;ERROR&quot; *.log</span></span>
<span class="line"><span># Find unique error patterns</span></span>
<span class="line"><span>grep &quot;ERROR&quot; *.log | cut -d&#39;]&#39; -f2 | sort | uniq -c | sort -rn</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 2: Timeline Analysis</span></span>
<span class="line"><span>- When did issues start?</span></span>
<span class="line"><span>- Are there patterns (time-based, load-based)?</span></span>
<span class="line"><span>- What happened before the first error?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 3: Correlation</span></span>
<span class="line"><span>- Do errors cluster together?</span></span>
<span class="line"><span>- Are multiple components affected?</span></span>
<span class="line"><span>- Is there a common root cause?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Log Analysis Report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Executive Summary</span></span>
<span class="line"><span>[1-2 sentence overview of findings]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Critical Issues (Immediate Action Required)</span></span>
<span class="line"><span>1. **[Issue Name]**</span></span>
<span class="line"><span>   - First occurrence: [timestamp]</span></span>
<span class="line"><span>   - Frequency: [count]</span></span>
<span class="line"><span>   - Impact: [description]</span></span>
<span class="line"><span>   - Recommended action: [action]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Warnings (Monitor)</span></span>
<span class="line"><span>- [Warning patterns and frequency]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Timeline</span></span>
<span class="line"><span>[Chronological sequence of events]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Root Cause Analysis</span></span>
<span class="line"><span>[Most likely root causes based on evidence]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Recommendations</span></span>
<span class="line"><span>1. [Prioritized action items]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Guidelines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Focus on actionable insights, not raw data</span></span>
<span class="line"><span>- Identify patterns, not just individual errors</span></span>
<span class="line"><span>- Consider cascading failures (one error causing others)</span></span>
<span class="line"><span>- Look for the FIRST error in a sequence</span></span>
<span class="line"><span>- Note any suspicious patterns (repeated IPs, unusual timing)</span></span>
<span class="line"><span>- Keep the summary concise - details only when necessary</span></span></code></pre></div><p>此处我们可以思考一下为什么刚才的测试运行器用 <code>haiku</code> 模型，而日志分析器用 sonnet？</p><p>因为测试运行器的任务是执行命令 + 解析结构化输出，这个任务的难度级别比较普通。而日志分析则需要完成后面这些需要更强推理能力的任务，所以 <code>sonnet</code> 更合适。</p><ul><li><p><strong>模式识别</strong>：从大量日志中识别重复出现的问题</p></li><li><p><strong>时序推理</strong>：理解哪个错误先发生，可能导致后续错误</p></li><li><p><strong>关联分析</strong>：数据库超时是否影响了 API 响应？</p></li><li><p><strong>根因分析</strong>：多个症状背后的真正原因是什么？</p></li></ul><h3 id="使用日志分析器" tabindex="-1">使用日志分析器 <a class="header-anchor" href="#使用日志分析器" aria-label="Permalink to &quot;使用日志分析器&quot;">​</a></h3><p>进入项目目录，在 Claude Code 中输入后面的内容。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>让 log-analyzer 分析 logs/ 目录下的错误，找出主要问题</span></span></code></pre></div><p>或者指定时间范围：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用 log-analyzer 分析 10:00-11:00 之间发生了什么问题</span></span></code></pre></div><p>示例输出如下。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### 示例输出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span>## Log Analysis Report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Executive Summary</span></span>
<span class="line"><span>系统在 10:25-10:45 期间经历了数据库连接池耗尽和 Redis 连接中断，导致多个 API 请求失败。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Critical Issues (Immediate Action Required)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **Database Connection Pool Exhausted**</span></span>
<span class="line"><span>   - First occurrence: 09:03:00</span></span>
<span class="line"><span>   - Frequency: 3 occurrences (09:03, 10:25, 10:25)</span></span>
<span class="line"><span>   - Impact: All database queries failing, pool status 0/10</span></span>
<span class="line"><span>   - Recommended action:</span></span>
<span class="line"><span>     - 检查是否有长时间运行的查询占用连接</span></span>
<span class="line"><span>     - 考虑增加连接池大小</span></span>
<span class="line"><span>     - 添加连接超时和重试机制</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. **Redis Connection Lost**</span></span>
<span class="line"><span>   - First occurrence: 10:45:30</span></span>
<span class="line"><span>   - Impact: Cache unavailable, may cause increased DB load</span></span>
<span class="line"><span>   - Recommended action:</span></span>
<span class="line"><span>     - 检查 Redis 服务器状态</span></span>
<span class="line"><span>     - 验证网络连接</span></span>
<span class="line"><span>     - 实现优雅降级（缓存不可用时直接查数据库）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Warnings (Monitor)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **Brute Force Attempt Detected**: IP 203.0.113.50 对 admin 账户进行了 5 次失败登录尝试</span></span>
<span class="line"><span>- **Rate Limiting Triggered**: IP 192.168.1.100 超出 /api/search 的速率限制</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Timeline</span></span>
<span class="line"><span>09:03:00 - 首次数据库超时 (可能是根因)</span></span>
<span class="line"><span>09:06:31 - 检测到暴力破解尝试</span></span>
<span class="line"><span>09:07:46 - 数据库死锁</span></span>
<span class="line"><span>09:35:15 - API 异常 (可能与数据库问题相关)</span></span>
<span class="line"><span>10:25:00 - 数据库超时再次出现 (问题未解决)</span></span>
<span class="line"><span>10:45:30 - Redis 连接丢失 (新问题)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Root Cause Analysis</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最可能的根因是**数据库连接池管理问题**：</span></span>
<span class="line"><span>1. 09:03 首次出现连接池耗尽</span></span>
<span class="line"><span>2. 后续多个组件受影响（订单服务、产品服务）</span></span>
<span class="line"><span>3. 10:25 问题再次出现，说明临时恢复但未根本解决</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Redis 问题可能是独立的基础设施问题，需要单独排查。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Recommendations</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **立即**: 检查数据库慢查询日志，找出耗时长的查询</span></span>
<span class="line"><span>2. **短期**: 增加数据库连接池监控告警</span></span>
<span class="line"><span>3. **中期**: 实现查询超时和连接释放机制</span></span>
<span class="line"><span>4. **长期**: 考虑读写分离，减轻主库压力</span></span></code></pre></div><p>原始日志可能有 100+ 行，但分析报告提炼出了可操作的洞察。</p><h2 id="输出格式设计方法论" tabindex="-1">输出格式设计方法论 <a class="header-anchor" href="#输出格式设计方法论" aria-label="Permalink to &quot;输出格式设计方法论&quot;">​</a></h2><p>你可能注意到了，上面的测试运行器和日志分析器都有精心设计的输出格式。这不是随意写的模板——输出格式的设计直接影响子代理的实用性。</p><p>为什么输出格式这么重要？子代理的输出是 <strong>主对话的输入</strong>。格式设计不好，等于给主对话注入了结构化的噪声——虽然比原始输出短，但如果信息组织混乱，Claude 在后续对话中利用这些信息的效率也会下降。</p><p>下面是我归纳出来的三层输出格式设计法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/773e26720d1d9725a15db4c0d2d016fd.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/773e26720d1d9725a15db4c0d2d016fd.jpg" alt=""></a></p><p>以测试运行器为例：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Test Results                    ← 第一层：一眼看到结果</span></span>
<span class="line"><span>**Status**: FAIL                   ← 立即做出&quot;需要处理&quot;的判断</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Failed Tests                   ← 第二层：具体哪些失败了</span></span>
<span class="line"><span>- \`test_name\`: reason              ← 可以直接定位问题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Recommendations                ← 第三层：可选的修复方向</span></span>
<span class="line"><span>- What to do next                  ← 只在有价值时才出现</span></span></code></pre></div><p>设计输出格式的四个原则是： <strong>结论先行、可操作性、分层详略</strong> 和 <strong>为下游消费设计。</strong></p><p>原则一：结论先行</p><p>这点很好理解，我们做个对比。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 好的格式</span></span>
<span class="line"><span>**Status**: FAIL               ← 第一眼就知道结果</span></span>
<span class="line"><span>**Failed**: 3 out of 47</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 差的格式</span></span>
<span class="line"><span>Running tests...</span></span>
<span class="line"><span>Test suite 1: calculator.test.js</span></span>
<span class="line"><span>  - add(1,2) = 3 ... PASS</span></span>
<span class="line"><span>  - subtract(5,3) = 2 ... PASS   ← 读了半天还不知道整体结果</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><p>原则二：可操作性</p><p>可操作性的衡量方法就是每条信息都应该能直接指导下一步行动。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 可操作</span></span>
<span class="line"><span>- [Form.test.js:45] email field empty after submit</span></span>
<span class="line"><span>  → Check Form component&#39;s handleSubmit, email state not bound</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 不可操作</span></span>
<span class="line"><span>- Some tests failed in the form module</span></span>
<span class="line"><span>  → Please check the code</span></span></code></pre></div><p>原则三：分层详略</p><p>该简单就简单，需要复杂就详述，需要合并就归总。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 全部通过时 → 极简</span></span>
<span class="line"><span>**Status**: PASS (47/47)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 少量失败时 → 展开失败项</span></span>
<span class="line"><span>**Status**: FAIL (44/47)</span></span>
<span class="line"><span>### Failed Tests</span></span>
<span class="line"><span>- test_1: reason</span></span>
<span class="line"><span>- test_2: reason</span></span>
<span class="line"><span>- test_3: reason</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 大量失败时 → 按类别归组</span></span>
<span class="line"><span>**Status**: FAIL (12/47)</span></span>
<span class="line"><span>### Failed Tests by Category</span></span>
<span class="line"><span>- Database connection (8 failures): DB server unreachable</span></span>
<span class="line"><span>- Auth token (3 failures): Token expired</span></span>
<span class="line"><span>- Input validation (1 failure): Missing null check</span></span></code></pre></div><p>原则四：为下游消费设计。</p><p>子代理的输出可能被主对话用来做后续决策。设计时要想好：“Claude 拿到这个输出后，能不能直接用？”</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 好：主对话可以直接基于此生成修复代码</span></span>
<span class="line"><span>### Failed Tests</span></span>
<span class="line"><span>- [src/form.js:45] \`handleSubmit\`: email state not updated</span></span>
<span class="line"><span>  - Root cause: setState call missing for email field</span></span>
<span class="line"><span>  - Fix: Add \`setEmail(e.target.value)\` in onChange handler</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 差：主对话还需要再去读文件才能理解</span></span>
<span class="line"><span>### Failed Tests</span></span>
<span class="line"><span>- Form submit test failed</span></span></code></pre></div><p>这个子代理输出的方法论，也是一套思维方法论，把它迁移到你的写作、口语表达、会议发言等生活实践也可以。</p><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><p>今天我们学习了如何创建处理 <strong>高噪声输出</strong> 的子代理。其核心价值是子代理去执行产生大量输出的任务，只把精炼的结论带回主对话，而主对话上下文保持清洁。</p><p>两个实战项目中测试运行器和日志分析器这两个子代理的对比如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/e87086b9e910e6a3af8260d7e585d85b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/944525/e87086b9e910e6a3af8260d7e585d85b.jpg" alt=""></a></p><p>虽有上述区别，但也不难看出这两个子代理的设计有一系列共同点。</p><ul><li><p>都是只读型：不需要 Edit/Write。</p></li><li><p>都处理高噪声，从大量输出中精炼出摘要。</p></li><li><p>都有结构化输出即明确的报告格式。</p></li><li><p>都是“隔离执行”，不污染主对话上下文。</p></li></ul><p>通过这两个项目，我们可以总结出设计高噪声处理型子代理的几个要点。</p><p><strong>1.定义好分析步骤</strong>：给子代理一个分析框架，帮助它系统地处理问题，而不是随意发散。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Analysis Approach</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 1: Quick Scan</span></span>
<span class="line"><span>### Step 2: Timeline Analysis</span></span>
<span class="line"><span>### Step 3: Correlation</span></span></code></pre></div><p><strong>2.选择合适的模型</strong>：不是所有子代理都需要最强的模型。根据任务复杂度选择，既省成本又快。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>haiku  ← 简单任务（执行、总结、模式匹配）</span></span>
<span class="line"><span>sonnet ← 复杂任务（分析、推理、关联）</span></span>
<span class="line"><span>opus   ← 最复杂任务（架构设计、深度推理）</span></span></code></pre></div><p><strong>3.强调简洁</strong>：在 prompt 中明确告诉子代理要简洁、可操作，否则它可能会返回过多细节。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Guidelines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Keep the summary SHORT - the user doesn&#39;t want to see raw logs</span></span>
<span class="line"><span>- Focus on actionable information</span></span></code></pre></div><p><strong>4.明确输出格式</strong>：子代理知道该返回什么、输出可预测、一致，而且易于自动化处理。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Output Format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Status**: PASS / FAIL</span></span>
<span class="line"><span>**Total**: X tests</span></span></code></pre></div><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你的项目中还有哪些高噪声输出的任务？它们适合用子代理来处理吗？为什么？</p></li><li><p>如果要创建一个“构建日志分析器“（分析 webpack/vite 等构建工具的输出），你会怎么设计它的 prompt？你会让这个SubAgent输出什么？</p></li></ol><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><p>下一讲我们将探索子代理的另外两个强大能力： <strong>并行探索</strong> 和 <strong>流水线编排</strong>。当你需要同时从多个角度分析问题，或者把复杂任务拆成多个阶段时，子代理的价值会更加凸显。</p><p>欢迎你在留言区和我交流讨论。如果这一讲对你有启发，别忘了分享给身边更多朋友。</p>`,121)])])}const g=n(l,[["render",i]]);export{h as __pageData,g as default};
